from collections import Counter

def get_mode(grid, r0, c0, r1, c1, exclude=0):
    values = []
    for r in range(r0, r1):
        for c in range(c0, c1):
            if grid[r][c] != exclude:
                values.append(grid[r][c])
    if not values:
        return 0
    counter = Counter(values).most_common(1)[0]
    return counter[0]

